async (page) => {
  const checks=[];
  const errors=[];
  page.on('pageerror',e=>errors.push(e.message));
  const ok=(value,label)=>{if(!value)throw Error(label);checks.push(label);};
  await page.goto('http://127.0.0.1:8767/');
  await page.emulateMedia({colorScheme:'light'});
  await page.setViewportSize({width:390,height:830});
  const f=page.frames().find(frame=>frame!==page.mainFrame());
  const button=name=>f.getByRole('button',{name,exact:true});
  const root=f.locator('#evently-premium');
  const capture=async(name)=>{
    await f.locator('.ep-body').evaluate(e=>e.scrollTop=0);
    await root.screenshot({path:'/Users/sellu/Desktop/event_planner/docs/design/evidence/'+name+'.png'});
  };
  await button('Start planning').click();
  await button('Birthday').click();
  await f.getByRole('button',{name:'Find my event team'}).click();
  await button('View Amber Events').click();
  await button('Services').click();
  await button('View Catering Buffet details').click();
  ok(await f.getByText('Birthday · 60 guests',{exact:true}).count()===1,'Service detail retains birthday and guest context');
  ok(await f.getByLabel('Plates',{exact:true}).inputValue()==='60','Catering defaults plate quantity from event guests');
  ok(await f.getByLabel('Dietary and serving requests').getAttribute('placeholder')==='Kids’ portions, allergies, cake service…','Catering prompts adapt to birthday');
  await f.getByLabel('Plates',{exact:true}).fill('80');
  await f.getByLabel('Menu preference').selectOption('Vegetarian');
  await f.getByLabel('Meal service').selectOption('Dinner');
  await f.getByLabel('Dietary and serving requests').fill('Nut-free options; 10 children’s portions');
  await capture('catering-service-details');
  await f.getByRole('button',{name:'Add service',exact:false}).click();
  ok(await f.locator('footer .ep-total').textContent()==='₹68,000','Vendor selection total reflects configured catering');
  await button('View Stage Decor details').click();
  ok(await f.getByLabel('Theme or colour palette').getAttribute('placeholder')==='e.g. Space theme, red and silver','Decoration has birthday-specific prompts');
  ok(await f.getByLabel('Menu preference').count()===0,'Decoration does not display catering fields');
  await f.getByLabel('Theme or colour palette').fill('Galaxy blue and silver');
  await f.getByLabel('Setup area').selectOption('Indoor');
  await f.getByLabel('Decoration requirements').fill('Cake table and star backdrop');
  await f.getByRole('button',{name:'Add service',exact:false}).click();
  await f.getByRole('button',{name:'Choose services',exact:false}).click();
  ok(await f.locator('input[data-service]:checked').count()===2,'Two services from one vendor remain selected');
  ok(await f.getByText('Menu preference: Vegetarian',{exact:true}).count()===1,'Selected catering displays its preferences');
  ok(await f.getByText('Theme or colour palette: Galaxy blue and silver',{exact:true}).count()===1,'Selected decoration displays separate preferences');
  await button('View Catering Buffet details').click();
  ok(await f.getByLabel('Menu preference').inputValue()==='Vegetarian','Reopening service preserves saved preference');
  ok(await f.getByLabel('Plates',{exact:true}).inputValue()==='80','Reopening service preserves saved quantity');
  await f.getByLabel('Plates',{exact:true}).fill('100');
  await f.getByRole('button',{name:'Save service details',exact:false}).click();
  ok(await f.locator('[data-total]').textContent()==='₹1,20,000','Editing one service recalculates the combined total');
  await button('View Event Lighting details').click();
  ok(await f.getByLabel('Hours',{exact:true}).count()===1,'Hourly service displays hours instead of plates');
  await f.getByLabel('Hours',{exact:true}).fill('2');
  await f.getByLabel('Event setup').selectOption('Outdoor');
  await f.getByLabel('Preferred start time').fill('18:00');
  await f.getByLabel('Sound or lighting requirements').fill('Warm cake-cutting lights');
  await f.getByRole('button',{name:'Add service',exact:false}).click();
  ok(await f.locator('[data-total]').textContent()==='₹1,25,000','Three configured services total correctly');
  await capture('configured-vendor-services');
  await f.getByRole('button',{name:'Review my selection',exact:false}).click();
  ok(await f.getByText('Menu preference: Vegetarian',{exact:true}).count()===1,'Review includes catering preferences');
  ok(await f.getByText('Theme or colour palette: Galaxy blue and silver',{exact:true}).count()===1,'Review includes decoration preferences');
  ok(await f.getByText('Preferred start time: 18:00',{exact:true}).count()===1,'Review includes lighting timing');
  await capture('service-preferences-review');
  await button('Edit').click();
  await button('View Stage Decor details').click();
  await button('Remove from selection').click();
  ok(await f.locator('[data-total]').textContent()==='₹90,000','Removing a service removes only its price');
  ok(await f.getByRole('checkbox',{name:'Select Catering Buffet',exact:true}).isChecked(),'Removing decoration keeps catering selected');
  await button('View Catering Buffet details').click();
  await f.getByLabel('Menu preference').selectOption('Mixed menu');
  await button('Go back').click();
  await button('View Catering Buffet details').click();
  ok(await f.getByLabel('Menu preference').inputValue()==='Vegetarian','Leaving without Save discards draft preferences');
  await button('Go back').click();
  await f.getByRole('button',{name:'Review my selection',exact:false}).click();
  ok(await f.getByText('Theme or colour palette: Galaxy blue and silver',{exact:true}).count()===0,'Removed service preferences are excluded from review');
  await f.getByRole('button',{name:'Preview booking request',exact:false}).click();
  await f.getByRole('button',{name:'See my event',exact:false}).click();
  ok(await f.getByText('Menu preference: Vegetarian',{exact:true}).count()===1,'Event draft stores its service preferences snapshot');
  await button('Explore').click();
  await button('Start planning').click();
  await button('Ring ceremony').click();
  await f.getByRole('button',{name:'Find my event team'}).click();
  await button('View Amber Events').click();
  await button('Services').click();
  await button('View Stage Decor details').click();
  ok(await f.getByLabel('Theme or colour palette').getAttribute('placeholder')==='e.g. Ivory florals with warm lighting','Same service adapts guidance for ring ceremony');
  ok(await f.getByLabel('Theme or colour palette').inputValue()==='','A new event starts with independent service preferences');
  await page.setViewportSize({width:320,height:830});
  await f.waitForFunction(()=>innerWidth===288);
  ok(await root.evaluate(e=>e.scrollWidth===e.clientWidth),'Service details have no horizontal overflow at 288px');
  await page.emulateMedia({colorScheme:'dark'});
  ok(await root.evaluate(e=>getComputedStyle(e).backgroundColor)==='rgb(29, 17, 23)','Service details support device dark appearance');
  await page.setViewportSize({width:390,height:830});
  await f.waitForFunction(()=>innerWidth===358);
  await capture('decoration-details-dark');
  await page.goto('http://127.0.0.1:8767/');
  await page.emulateMedia({colorScheme:'light'});
  const fresh=page.frames().find(frame=>frame!==page.mainFrame());
  await fresh.getByRole('button',{name:'View all',exact:true}).click();
  await fresh.getByRole('button',{name:'View Frame & Light Studio',exact:true}).click();
  await fresh.getByRole('button',{name:'Services',exact:true}).click();
  await fresh.getByRole('button',{name:'View Candid Photographer details',exact:true}).click();
  await fresh.getByRole('button',{name:'Add service',exact:false}).click();
  await fresh.getByRole('button',{name:'View Photo Album details',exact:true}).click();
  ok(await fresh.getByText('One-service mode: adding this replaces your current selection.',{exact:true}).count()===1,'One-service replacement is disclosed before adding');
  await fresh.getByRole('button',{name:'Add service',exact:false}).click();
  await fresh.getByRole('button',{name:'Choose services',exact:false}).click();
  ok(await fresh.locator('input[data-service]:checked').count()===1,'Adding in one-service mode replaces existing service');
  await fresh.getByRole('button',{name:'Multiple services',exact:true}).click();
  await fresh.getByRole('checkbox',{name:'Select Candid Photographer',exact:true}).check();
  ok(await fresh.locator('input[data-service]:checked').count()===2,'Service-first customer can choose several vendor services');
  await fresh.getByLabel('Occasion (optional)').fill('Corporate');
  await fresh.getByLabel('Occasion (optional)').press('Tab');
  await fresh.getByRole('button',{name:'View Candid Photographer details',exact:true}).click();
  ok(await fresh.getByText('Corporate',{exact:true}).count()===1,'Standalone services support occasion context without creating an event');
  ok(errors.length===0,'No runtime errors in service-detail journey');
  await page.goto('http://127.0.0.1:8767/');
  return {checks,errors};
}
